import React, { useState, useEffect } from 'react';
import { FaHeart, FaTrash } from 'react-icons/fa';
import styles from './BlogCard.module.css';
import PropTypes from 'prop-types';

const BlogCard = ({ title, category, excerpt, image, date, createdAt, publishedAt, onDelete, id, _id }) => {
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    checkAdminStatus();
  }, []);

  const checkAdminStatus = () => {
    try {
      const userInfo = localStorage.getItem('userInfo');
      if (userInfo) {
        const user = JSON.parse(userInfo);
        if (user && user.role === 'admin') {
          setIsAdmin(true);
        }
      }
    } catch (err) {
      console.error('Error checking admin status:', err);
    }
  };

  // Determine the date to display
  const displayDate = date || 
                     (publishedAt && new Date(publishedAt).toLocaleDateString()) || 
                     (createdAt && new Date(createdAt).toLocaleDateString()) || 
                     'No date';

  // Determine the ID to use for deletion
  const blogId = id || _id;

  // Use a default image if none is provided
  const blogImage = image || 'https://via.placeholder.com/300x200?text=Blog+Post';

  // Determine the category label
  const categoryLabel = category === 'budget' ? 'BUDGET' : 
                       (category ? `${category.toUpperCase()} FAVES` : 'GENERAL');

  return (
    <div className={styles.blogCard}>
      <div className={styles.imageWrapper}>
        <img src={blogImage} alt={title} className={styles.blogImage} />
        <div className={styles.overlay}></div>
      </div>
      <div className={styles.cardContent}>
        <h3 className={styles.cardTitle}>{title}</h3>
        <p className={styles.categoryLabel}>{categoryLabel}</p>
        <p className={styles.date}>{displayDate}</p>
        <FaHeart className={styles.heartIcon} />
        {isAdmin && blogId && (
          <FaTrash 
            className={styles.deleteIcon} 
            onClick={() => onDelete(blogId)} 
            title="Delete blog post"
          />
        )}
      </div>
    </div>
  );
};

BlogCard.propTypes = {
  title: PropTypes.string.isRequired,
  category: PropTypes.string,
  excerpt: PropTypes.string,
  image: PropTypes.string,
  date: PropTypes.string,
  createdAt: PropTypes.string,
  publishedAt: PropTypes.string,
  onDelete: PropTypes.func.isRequired,
  id: PropTypes.string,
  _id: PropTypes.string
};

export default BlogCard;
